// Generate reference from the actual package export map and compiler export symbols.
// No copied API declarations. --check rejects any stale/missing generated bytes.
import assert from "node:assert/strict"
import { execFileSync } from "node:child_process"
import { createHash } from "node:crypto"
import { mkdirSync, readFileSync, writeFileSync } from "node:fs"
import { resolve, join } from "node:path"
import { API, SymbolFlags } from "typescript/unstable/sync"

const root = resolve(import.meta.dirname, "../../../..")
const output = join(root, "apps/website/src/content/docs/reference")
const manifest = JSON.parse(readFileSync(join(root, "package.json"), "utf8"))
const groups = {
  definitions: {
    title: "Definitions and production",
    intro:
      "Declare logical queues and versioned payloads, then identify each business consequence. Constructors do not create storage or start workers. The root entrypoint intentionally exports nothing; use the focused subpaths below.",
    modules: [
      "index",
      "Job",
      "JobQueue",
      "JobProducer",
      "JobIdentity",
      "JobId",
      "JobContract",
      "JobEnqueue",
      "JobTransaction"
    ]
  },
  payloads: {
    title: "Payloads and policy",
    intro:
      "Schema owns the encoded/domain boundary. Protected markers and encrypted transformations do not supply cryptographic keys or algorithms. Persisted policy is first-write-wins; a matching duplicate does not refresh its retention or retry budget.",
    modules: ["JobPayload", "JobPayloadCodec", "JobPolicy", "JobFailure", "FailureCode"]
  },
  workers: {
    title: "Handlers and workers",
    intro:
      "Install handlers in a shared registry before constructing a worker. A finite drain and a scoped polling Layer are separate operations. Local permits bound claims for one worker; they do not provide global concurrency or exactly-once external delivery.",
    modules: [
      "JobRegistry",
      "JobConsumer",
      "JobWorker",
      "JobWorkerRuntime",
      "PollingJobWorker"
    ]
  },
  lifecycle: {
    title: "Lifecycle and operator ports",
    intro:
      "These are backend and application integration contracts. Handlers receive payload and metadata, never lease tokens or finalization authority. Database time and exact ownership fencing remain backend responsibilities. OutcomeUnknown is an attempt outcome, not a durable state.",
    modules: ["JobLifecycle", "JobStore", "JobOperators"]
  },
  postgresql: {
    title: "PostgreSQL integration",
    intro:
      "The application owns migrations, one configured native client, finite control timeouts and pool lifetime. Use the same PgClient for domain writes and enqueue. Runtime imports do no SQL. Drizzle declarations are optional and do not themselves qualify a transaction adapter.",
    modules: [
      "PostgreSqlJobs",
      "PostgreSqlTransaction",
      "PostgreSqlNative",
      "PostgreSqlSchema",
      "PostgreSqlDrizzleSchema"
    ]
  }
}
const exportedModules = Object.keys(manifest.exports).map((key) =>
  key === "." ? "index" : key.slice(2)
)
const assigned = Object.values(groups).flatMap((group) => group.modules)
assert.deepEqual(
  [...assigned].sort(),
  [...exportedModules].sort(),
  "Every public subpath needs exactly one reference group"
)
assert.equal(new Set(assigned).size, assigned.length)
const api = new API({ cwd: root })
process.on("exit", () => api.close())
const snapshot = api.updateSnapshot({ openProjects: [join(root, "tsconfig.build.json")] })
const project = snapshot.getProject(join(root, "tsconfig.build.json"))
assert(project, "Build project must be available to the pinned TypeScript compiler")
const { program, checker } = project
const escaped = (value) =>
  value
    .replaceAll("|", "&#124;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll("{", "&#123;")
    .replaceAll("}", "&#125;")
    .replace(/\s+/g, " ")
    .trim()
const inventory = []
mkdirSync(output, { recursive: true })
for (const [slug, group] of Object.entries(groups)) {
  let body = `---\ntitle: ${group.title}\ndescription: Source-derived public API reference for ${group.title.toLowerCase()}.\n---\n\n{/* Generated by tests/docs-reference/Reference.mjs. Edit public source JSDoc, then regenerate. */}\n\n${group.intro}\n\nNames, symbol kinds and descriptions below are extracted from current public exports, including re-exports. Complete types remain in the package declarations; these tables do not maintain a second declaration set. See [checked examples](/docs/reference/examples/) for composition.\n`
  for (const name of group.modules) {
    const filename = `src/${name}.ts`
    const file = program.getSourceFile(join(root, filename))
    assert(file, `Missing ${filename}`)
    const module = checker.getSymbolAtLocation(file)
    assert(module, `Not a module: ${filename}`)
    const exports = [...checker.getExportsOfModule(module)].sort((a, b) =>
      a.name.localeCompare(b.name, "en")
    )
    const symbols = exports.map((symbol) => {
      const target =
        symbol.flags & SymbolFlags.Alias ? checker.getAliasedSymbol(symbol) : symbol
      const descriptions = target.getDocumentationComment(checker).split(/\n\s*\n/)[0]
      const tags = target.getJsDocTags(checker)
      const category = tags.find((tag) => tag.name === "category")?.text
      // Merged Schema/type names are represented once; both namespaces stay explicit.
      const namespaces = [
        target.flags & SymbolFlags.Value ? "value" : null,
        target.flags & SymbolFlags.Type ? "type" : null
      ]
        .filter(Boolean)
        .join(" + ")
      return {
        name: symbol.name,
        kind: namespaces,
        category: category ?? "contract",
        description:
          descriptions || "Public integration contract; see the exported declaration."
      }
    })
    const subpath = name === "index" ? "effect-jobs" : `effect-jobs/${name}`
    inventory.push({
      subpath,
      filename,
      sha256: createHash("sha256")
        .update(readFileSync(join(root, filename)))
        .digest("hex"),
      symbols
    })
    body += `\n## ${name === "index" ? "Root entrypoint" : name}\n\nImport: \`${subpath}\`. Source: \`${filename}\`.\n\n`
    if (symbols.length === 0) {
      body += "This entrypoint is intentionally empty. Import a focused subpath.\n"
    } else {
      body += "| Export | Kind | Contract |\n| --- | --- | --- |\n"
      for (const symbol of symbols) {
        body += `| \`${symbol.name}\` | ${symbol.kind} | ${escaped(symbol.description)} |\n`
      }
    }
  }
  const path = join(output, `${slug}.mdx`)
  body = execFileSync(
    join(root, "node_modules/.bin/oxfmt"),
    ["--config", join(root, ".oxfmtrc.json"), "--stdin-filepath", path],
    { input: body, encoding: "utf8" }
  )
  if (process.argv.includes("--check")) {
    assert.equal(readFileSync(path, "utf8"), body, `Stale reference: ${path}`)
  } else {
    writeFileSync(path, body)
  }
}
const path = join(output, "public-exports.json")
const bytes = JSON.stringify(inventory, null, 2) + "\n"
if (process.argv.includes("--check")) {
  assert.equal(readFileSync(path, "utf8"), bytes, "Stale export inventory")
} else {
  writeFileSync(path, bytes)
}
console.log(
  `${inventory.length} public entrypoints, ${inventory.reduce((n, item) => n + item.symbols.length, 0)} exported names: reference ${process.argv.includes("--check") ? "consistent" : "generated"}`
)

snapshot.dispose()
api.close()
